This Terraform configuration provisions an AWS Lightsail SSL/TLS certificate for a domain name, including optional subject alternative names such as `www.example.com`. The certificate will be created in AWS Lightsail and will require DNS validation before it becomes active.

```hcl
terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  description = "AWS region to use for the Lightsail certificate."
  type        = string
  default     = "us-east-1"
}

variable "certificate_name" {
  description = "Name of the Lightsail certificate."
  type        = string
  default     = "example-lightsail-certificate"
}

variable "domain_name" {
  description = "Primary domain name for the Lightsail certificate."
  type        = string
  default     = "example.com"
}

variable "subject_alternative_names" {
  description = "Additional domain names to include in the Lightsail certificate."
  type        = list(string)
  default     = ["www.example.com"]
}

